/**
 * Sample graphs for the shader lab: generated by graph-samples, laid out by layout, measured by
 * algorithms, and flattened into the per-node and per-edge numbers the shaders read.
 * Every graph is deterministic for its arguments and cached, so switching stories is instant.
 */
import { louvain, pageRank } from "@graphty/algorithms";
import { fromEdgeArrays } from "@graphty/graph-format";
import { barabasiAlbertGraph, layeredFlowNetwork, plantedPartitionGraph } from "@graphty/graph-samples/generators";
import { forceAtlas2 } from "@graphty/layout";

/** The sample graphs a story can ask for. */
export type GraphKind = "communities" | "large" | "flow" | "weighted";

export const GRAPH_KINDS: GraphKind[] = ["communities", "large", "flow", "weighted"];

/** A graph ready to draw. Every per-node array is indexed by node index, per-edge by edge index. */
export interface LabGraph {
    kind: GraphKind;
    n: number;
    m: number;
    dim: 2 | 3;
    directed: boolean;
    /** xyz per node (z = 0 in 2D), the layout scaled to about 100 world units across. */
    pos: Float32Array;
    /** A good node radius in world units for this graph's density. */
    nodeRadius: number;
    src: Uint32Array;
    dst: Uint32Array;
    /** Community (or layer, for the flow graph) per node, 0..communityCount-1. */
    community: Uint32Array;
    communityCount: number;
    /** Degree / max degree, 0..1. */
    degree: Float32Array;
    /** PageRank / max PageRank, 0..1. */
    rank: Float32Array;
    /** A smooth 0..1 value per node (its random averaged with its neighbors'), for gauges and fills. */
    value: Float32Array;
    /** A stable random 0..1 per node. */
    random: Float32Array;
    /** Edge weight normalized to 0..1 (random when the graph is unweighted). */
    weight: Float32Array;
    /** Neighbor lists. */
    neighbors: number[][];
}

/** Options of {@link makeGraph}. */
export interface GraphOptions {
    /** Rough node count (0 or absent = the kind's default); each kind rounds it to its own shape. */
    nodes?: number;
    seed?: number;
    dim?: 2 | 3;
}

const cache = new Map<string, LabGraph>();

/** Fewer layout iterations for big graphs, so a story opens in a few seconds. */
function iterationsFor(n: number): number {
    if (n > 3000) {
        return 30;
    }
    return n > 1000 ? 60 : 150;
}

function hash01(i: number, seed: number): number {
    let h = Math.imul(i ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(seed + 1, 0xc2b2ae35);
    h = Math.imul(h ^ (h >>> 13), 0x27d4eb2f);
    h ^= h >>> 16;
    return (h >>> 0) / 4294967296;
}

function normalize(values: ArrayLike<number>): Float32Array {
    let max = 0;
    for (let i = 0; i < values.length; i++) {
        max = Math.max(max, values[i]);
    }
    const out = new Float32Array(values.length);
    for (let i = 0; i < values.length; i++) {
        out[i] = max > 0 ? values[i] / max : 0;
    }
    return out;
}

const DEFAULT_NODES: Record<GraphKind, number> = { communities: 240, large: 2500, flow: 120, weighted: 400 };

/**
 * A sample graph with positions and per-node measures.
 * - communities: planted partition, 8 groups, ground-truth communities (about 240 nodes)
 * - large: planted partition, 12 groups (about 2500 nodes)
 * - flow: layered directed flow network, source on the left, sink on the right; community = layer
 * - weighted: Barabasi-Albert scale-free graph with exponential weights; communities by Louvain
 * @param kind - which graph
 * @param options - node count, seed, 2D or 3D
 * @returns the graph (cached by its arguments)
 */
export function makeGraph(kind: GraphKind = "communities", options: GraphOptions = {}): LabGraph {
    const seed = options.seed ?? 1;
    const dim = options.dim ?? 3;
    const want = options.nodes || DEFAULT_NODES[kind];
    const key = `${kind}/${want}/${seed}/${dim}`;
    const hit = cache.get(key);
    if (hit) {
        return hit;
    }

    let sample;
    let community: Uint32Array | undefined;
    let layerX: Float32Array | undefined;
    if (kind === "communities" || kind === "large") {
        const groups = kind === "large" ? 12 : 8;
        const groupSize = Math.max(2, Math.round(want / groups));
        const avgIn = kind === "large" ? 7 : 5;
        sample = plantedPartitionGraph({
            groups,
            groupSize,
            pIn: Math.min(1, avgIn / groupSize),
            pOut: 0.6 / (groupSize * groups),
            seed,
            weights: { kind: "uniform" },
        });
        community = Uint32Array.from(sample.nodeColumns?.community as ArrayLike<number>);
    } else if (kind === "flow") {
        const width = Math.max(2, Math.round(want / 12));
        const layers = [0.5, 1, 1.5, 2, 1.5, 1, 0.5].map((f) => Math.max(1, Math.round(width * f)));
        const flow = layeredFlowNetwork({ layers, p: Math.min(1, 3 / width), seed });
        sample = flow;
        // community = layer: source 0, inner layers 1..L, sink L+1
        const layerOf = new Uint32Array(flow.nodeCount);
        let idx = 0;
        layers.forEach((size, li) => {
            for (let k = 0; k < size; k++) {
                layerOf[idx++] = li + 1;
            }
        });
        community = layerOf;
        community[flow.source] = 0;
        community[flow.sink] = layers.length + 1;
        layerX = new Float32Array(flow.nodeCount);
        for (let i = 0; i < flow.nodeCount; i++) {
            layerX[i] = (community[i] / (layers.length + 1)) * 100 - 50;
        }
    } else {
        sample = barabasiAlbertGraph({ n: want, m: 2, seed, weights: { kind: "exponential" } });
    }

    const n = sample.nodeCount;
    const src = Uint32Array.from(sample.src);
    const dst = Uint32Array.from(sample.dst);
    const m = src.length;
    const snapshot = fromEdgeArrays({ directed: sample.directed, nodeCount: n, src, dst });

    if (!community) {
        community = Uint32Array.from(louvain(snapshot).labels as ArrayLike<number>);
    }
    let communityCount = 0;
    for (let i = 0; i < n; i++) {
        communityCount = Math.max(communityCount, community[i] + 1);
    }

    const layout = forceAtlas2(snapshot, { dim, seed, maxIter: iterationsFor(n), scale: 50 });
    const pos = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
        pos[i * 3] = layout.positions[i * dim];
        pos[i * 3 + 1] = layout.positions[i * dim + 1];
        pos[i * 3 + 2] = dim === 3 ? layout.positions[i * dim + 2] : 0;
        if (layerX) {
            pos[i * 3] = layerX[i];
        }
    }

    if (layerX) {
        // flow: each layer a column, its nodes spread evenly in the layout's vertical order
        const byLayer = new Map<number, number[]>();
        for (let i = 0; i < n; i++) {
            byLayer.set(community[i], [...(byLayer.get(community[i]) ?? []), i]);
        }
        for (const members of byLayer.values()) {
            members.sort((p, q) => pos[p * 3 + 1] - pos[q * 3 + 1]);
            members.forEach((i, k) => (pos[i * 3 + 1] = (k - (members.length - 1) / 2) * 8));
        }
    }
    // center, and scale so 95% of nodes sit within 50 units of the center (outliers stay outside)
    const mean = [0, 1, 2].map((k) => {
        let s = 0;
        for (let i = 0; i < n; i++) {
            s += pos[i * 3 + k];
        }
        return s / n;
    });
    const dist: number[] = [];
    for (let i = 0; i < n; i++) {
        for (let k = 0; k < 3; k++) {
            pos[i * 3 + k] -= dim === 2 && k === 2 ? 0 : mean[k];
        }
        dist.push(Math.hypot(pos[i * 3], pos[i * 3 + 1], pos[i * 3 + 2]));
    }
    dist.sort((p, q) => p - q);
    const fit = 50 / Math.max(1e-6, dist[Math.floor(n * 0.95)] ?? 1);
    for (let i = 0; i < pos.length; i++) {
        pos[i] *= fit;
    }

    const neighbors: number[][] = Array.from({ length: n }, () => []);
    const deg = new Float32Array(n);
    for (let e = 0; e < m; e++) {
        neighbors[src[e]].push(dst[e]);
        neighbors[dst[e]].push(src[e]);
        deg[src[e]]++;
        deg[dst[e]]++;
    }
    const random = new Float32Array(n);
    for (let i = 0; i < n; i++) {
        random[i] = hash01(i, seed);
    }
    const value = new Float32Array(n);
    for (let i = 0; i < n; i++) {
        let sum = random[i];
        for (const j of neighbors[i]) {
            sum += random[j];
        }
        value[i] = sum / (neighbors[i].length + 1);
    }
    // stretch the averaged values back out to 0..1
    let lo = 1;
    let hi = 0;
    for (const v of value) {
        lo = Math.min(lo, v);
        hi = Math.max(hi, v);
    }
    for (let i = 0; i < n; i++) {
        value[i] = hi > lo ? (value[i] - lo) / (hi - lo) : 0.5;
    }

    const weight = sample.weights
        ? normalize(sample.weights)
        : Float32Array.from({ length: m }, (_, e) => hash01(e, seed + 7));

    const spacing = dim === 3 ? 100 / Math.cbrt(n) : 100 / Math.sqrt(n);
    const graph: LabGraph = {
        kind,
        n,
        m,
        dim,
        directed: sample.directed,
        pos,
        nodeRadius: Math.min(2, 0.11 * spacing),
        src,
        dst,
        community,
        communityCount,
        degree: normalize(deg),
        rank: normalize(pageRank(snapshot).scores),
        value,
        random,
        weight,
        neighbors,
    };
    cache.set(key, graph);
    return graph;
}

/**
 * Breadth-first hop counts from one node (-1 where unreachable, edges ignored for direction).
 * @param graph - the graph
 * @param start - the node
 * @returns hops per node
 */
export function hopsFrom(graph: LabGraph, start: number): Int32Array {
    const hops = new Int32Array(graph.n).fill(-1);
    hops[start] = 0;
    const queue = [start];
    for (let q = 0; q < queue.length; q++) {
        const u = queue[q];
        for (const v of graph.neighbors[u]) {
            if (hops[v] < 0) {
                hops[v] = hops[u] + 1;
                queue.push(v);
            }
        }
    }
    return hops;
}

/** A categorical palette (12 colors, linear 0..1 RGB-ish sRGB values). */
export const PALETTE: [number, number, number][] = [
    "#4e79a7",
    "#f28e2b",
    "#e15759",
    "#76b7b2",
    "#59a14f",
    "#edc948",
    "#b07aa1",
    "#ff9da7",
    "#9c755f",
    "#bab0ac",
    "#17becf",
    "#bcbd22",
].map((hex) => [
    parseInt(hex.slice(1, 3), 16) / 255,
    parseInt(hex.slice(3, 5), 16) / 255,
    parseInt(hex.slice(5, 7), 16) / 255,
]);

/**
 * The palette color of a community.
 * @param c - community id
 * @returns rgb 0..1
 */
export function communityColor(c: number): [number, number, number] {
    return PALETTE[c % PALETTE.length];
}
